1	/**
2	 * `run`: the whole pipeline, on one application, in one command.
3	 *
4	 * Every stage in this directory was proven on its own before this module
5	 * existed, and `migrate` reaches most of them only when each is opted into.
6	 * That is deliberate and stays: `migrate`'s exit-0 path has to remain runnable
7	 * with no registry, and a stage it was never asked for has to be recorded as
8	 * not run rather than implied. So this is the other entry beside it — the one
9	 * whose answer is "what does this application do when all nine stages are
10	 * asked for" — and it adds no migration decision of its own.
11	 *
12	 * Three properties are structural rather than convenient.
13	 *
14	 * **It composes; it does not reimplement.** Each stage here is the same
15	 * exported function the single-stage command composes, called with the same
16	 * declarations. A policy nobody declared refuses exactly where it refuses when
17	 * the stage is invoked alone, because it is the same guard.
18	 *
19	 * **The first refusing stage settles the run.** Its refusal is carried
20	 * verbatim, the exit code is 2, and every later stage is recorded not-run with
21	 * that stage named. Nothing here catches a refusal in order to keep going: a
22	 * chained run that stepped over a refused migration would report a lane the
23	 * pipeline declined to make.
24	 *
25	 * **One seam.** `runStage` is the only place a stage begins and ends. The
26	 * timestamps, the status and the refusal capture all live in it, so a later
27	 * reading that needs to count something per stage has one place to instrument
28	 * rather than nine call sites to find.
29	 */
30	
31	import { readFile } from 'node:fs/promises';
32	import * as path from 'pathe';
33	import {
34		COVERAGE_REPORT_SCHEMA,
35		coverageReportDigest,
36		type CoverageReport,
37	} from '../../../trust/src/coverage-report.ts';
38	import { analyzeApplication, fileExists } from './analyze.ts';
39	import { applyPlan } from './apply.ts';
40	import { runLaneBuild } from './build.ts';
41	import { establishEraCell, type EraCellDeclarations } from './era-cell.ts';
42	import { ingestApplicationSource, type IngestDeclarations } from './ingest.ts';
43	import { writeLaneFiles } from './lane.ts';
44	import { readLicenceAtPin, type LicencePolicy } from './license.ts';
45	import { runLaneInstall, type InstallPolicy } from './install.ts';
46	import { planApplication } from './plan.ts';
47	import { composeLane, displayPath } from './record.ts';
48	import {
49		EXIT_DEFECT,
50		EXIT_PROCEEDED,
51		EXIT_REFUSAL,
52		pipelineRefusalOf,
53		renderRefusal,
54		type PipelineRefusal,
55	} from './refusals.ts';
56	import { runLaneWitness } from './witness.ts';
57	
58	export const RUN_SCHEMA = 'versionless.run.v1';
59	
60	/**
61	 * The slot the coverage report occupies.
62	 *
63	 * `run` does not derive that document and does not regenerate the trust package
64	 * to refresh it: it points at what the guarded derivation emitted. Pointing is
65	 * the whole contract, so the three readings this seam can take are all recorded
66	 * as what they are — the report is there and internally consistent, it is there
67	 * and does not recompute to its own digest, or it is not there at all.
68	 */
69	export const RUN_COVERAGE_REPORT_SLOT = 'evidence/trust/current/coverage-report.json';
70	
71	export type RunReportSlot =
72		| Readonly<{ status: 'emitted'; slot: string; path: string; digest: string }>
73		| Readonly<{ status: 'not-yet-emitted' | 'stale'; slot: string; reason: string }>;
74	
75	/**
76	 * Read the emitted coverage report, or say honestly why this is not one.
77	 *
78	 * The digest is recomputed over the published record rather than trusted from
79	 * the field it carries, so a report edited after emission reads `stale` here
80	 * instead of being pointed at as if it were derived. What this cannot establish
81	 * is freshness with respect to *this* run: keeping the report current across a
82	 * rebuild is the generator's ordering problem, not this seam's.
83	 */
84	export async function readCoverageReportSlot(rootDir = '.'): Promise<RunReportSlot> {
85		const file = path.join(rootDir, RUN_COVERAGE_REPORT_SLOT);
86		let body: string;
87		try {
88			body = await readFile(file, 'utf8');
89		} catch {
90			return Object.freeze({
91				status: 'not-yet-emitted' as const,
92				slot: RUN_COVERAGE_REPORT_SLOT,
93				reason: 'no coverage report is published at the slot',
94			});
95		}
96		let report: CoverageReport;
97		try {
98			report = JSON.parse(body) as CoverageReport;
99		} catch {
100			return Object.freeze({
101				status: 'stale' as const,
102				slot: RUN_COVERAGE_REPORT_SLOT,
103				reason: 'the published coverage report is not readable JSON',
104			});
105		}
106		if (report.schemaVersion !== COVERAGE_REPORT_SCHEMA)
107			return Object.freeze({
108				status: 'stale' as const,
109				slot: RUN_COVERAGE_REPORT_SLOT,
110				reason: `the published coverage report carries schema ${String(report.schemaVersion)} rather than ${COVERAGE_REPORT_SCHEMA}`,
111			});
112		if (coverageReportDigest(report) !== report.integrity.canonicalDigest)
113			return Object.freeze({
114				status: 'stale' as const,
115				slot: RUN_COVERAGE_REPORT_SLOT,
116				reason: 'the published coverage report does not recompute to its own canonical digest',
117			});
118		return Object.freeze({
119			status: 'emitted' as const,
120			slot: RUN_COVERAGE_REPORT_SLOT,
121			path: RUN_COVERAGE_REPORT_SLOT,
122			digest: report.integrity.canonicalDigest,
123		});
124	}
125	
126	/**
127	 * The stages, in the order they run.
128	 *
129	 * The order is not a preference. Admission precedes composition because a
130	 * licence nobody read is a reason not to compose a lane at all; the cell
131	 * precedes the install because the install runs inside it; the witness is last
132	 * because there is nothing to witness until something has been emitted.
133	 */
134	export const RUN_STAGES = [
135		'analyze',
136		'ingest',
137		'license-at-pin',
138		'era-cell',
139		'plan',
140		'apply',
141		'install',
142		'build',
143		'witness',
144	] as const;
145	
146	export type RunStageName = (typeof RUN_STAGES)[number];
147	
148	/** Which stage owns which declaration. `run` forwards and owns none of them. */
149	export const RUN_STAGE_FLAGS: Readonly<Record<RunStageName, readonly string[]>> = Object.freeze({
150		analyze: Object.freeze([]),
151		ingest: Object.freeze([
152			'--source-root',
153			'--id',
154			'--frontend-root',
155			'--revision',
156			'--repository',
157			'--ref',
158			'--lockfile',
159			'--license',
160		]),
161		'license-at-pin': Object.freeze(['--frontend-root', '--license']),
162		'era-cell': Object.freeze(['--cell', '--node', '--arch']),
163		plan: Object.freeze(['--source-dir', '--template-dir', '--style-dir', '--entry']),
164		apply: Object.freeze(['--out', '--materialize']),
165		install: Object.freeze([
166			'--allow-remote-tarballs',
167			'--allow-install-scripts',
168			'--skip-install-scripts',
169			'--allow-peer-conflicts',
170		]),
171		build: Object.freeze([]),
172		witness: Object.freeze([]),
173	});
174	
175	export type RunStageStatus = 'ran' | 'not-run' | 'refused' | 'defect';
176	
177	export type RunStageRow = Readonly<{
178		name: RunStageName;
179		status: RunStageStatus;
180		/** Why the stage did not run, or what broke in it. */
181		reason?: string;
182		refusal?: PipelineRefusal;
183		/** The record the stage itself produced, unaltered. */
184		record?: unknown;
185		startedAt: string;
186		endedAt: string;
187	}>;
188	
189	export type RunStagePlanRow = Readonly<{
190		name: RunStageName;
191		/** The declarations from this command line the stage is given. */
192		forwards: readonly string[];
193	}>;
194	
195	export type RunRecord = Readonly<{
196		schema: string;
197		flow: 'run';
198		outcome: 'proceeded' | 'refused' | 'defect' | 'not-run';
199		exitCode: number;
200		application: string;
201		lane: string;
202		dryRun: boolean;
203		stagePlan: readonly RunStagePlanRow[];
204		stages: readonly RunStageRow[];
205		refusal?: PipelineRefusal;
206		defect?: Readonly<{ stage: RunStageName; message: string }>;
207		report: RunReportSlot;
208		notEstablished: readonly string[];
209	}>;
210	
211	/** What the report slot does not establish, in each of its three readings. */
212	const REPORT_NOT_ESTABLISHED: Readonly<Record<RunReportSlot['status'], string>> = Object.freeze({
213		emitted: `The coverage report at ${RUN_COVERAGE_REPORT_SLOT} was emitted by the guarded derivation and recomputes to the digest recorded here. This run did not derive it, did not regenerate it, and establishes nothing about whether it is current with respect to this run.`,
214		stale: `A file exists at ${RUN_COVERAGE_REPORT_SLOT} and is not the report this run may point at: it does not recompute to its own canonical digest or does not carry the coverage schema. Nothing here establishes what a regenerated report would say.`,
215		'not-yet-emitted': `No coverage report is published at ${RUN_COVERAGE_REPORT_SLOT}. This run did not emit one; a reader who needs coverage has to derive it elsewhere.`,
216	});
217	
218	const RUN_NOT_ESTABLISHED: readonly string[] = Object.freeze([
219		'A stage recorded `ran` returned its own record. What that record establishes is what that stage states, and no more: this row adds no reading of its own on top of it.',
220		'A stage recorded `not-run` was not reached, because an earlier stage refused or broke. Nothing here establishes what it would have recorded.',
221		'Exit 2 is a refusal and exit 1 is a defect. A crash, a hang, or a tree that will not install is a defect even when it happens inside a stage that can also refuse.',
222		'The stage timestamps bound the wall-clock interval the seam observed around each stage. They are not a measurement of machine time and they are not comparable across hosts.',
223	]);
224	
225	export type RunDeclarations = Readonly<{
226		appRoot: string;
227		out: string;
228		/** The repository root the ingest stage reads; defaults to the app root. */
229		sourceRoot: string;
230		materialize: boolean;
231		dryRun: boolean;
232		ingest: IngestDeclarations;
233		licence: LicencePolicy;
234		eraCell: EraCellDeclarations;
235		angular: Readonly<{
236			sourceDirectories?: readonly string[] | undefined;
237			templateDirectories?: readonly string[] | undefined;
238			styleSheetDirectories?: readonly string[] | undefined;
239		}>;
240		react: Readonly<{ entryModule?: string | undefined }>;
241		install: InstallPolicy;
242		/** The flags this command line carried, for the forwarding table. */
243		flags: Readonly<Record<string, readonly string[]>>;
244	}>;
245	
246	/** Why the stages after the one that stopped the run were not reached. */
247	function notRunBecause(stage: RunStageName, status: 'refused' | 'defect'): string {
248		return `not-run-because: ${stage} ${status === 'refused' ? 'refused' : 'raised a defect'}`;
249	}
250	
251	type RunState = {
252		readonly rows: RunStageRow[];
253		/** The stage that stopped the run, once one has. */
254		halted: Readonly<{ stage: RunStageName; status: 'refused' | 'defect' }> | null;
255		refusal: PipelineRefusal | null;
256		defect: Readonly<{ stage: RunStageName; message: string }> | null;
257	};
258	
259	/**
260	 * The stage seam: the one place a stage begins and ends.
261	 *
262	 * Everything a reader can say per stage is decided here — when it started,
263	 * when it ended, whether it ran, and what it refused with. A stage after the
264	 * run has halted is recorded rather than skipped silently, because a table
265	 * missing its later rows reads as a run that was never asked for them.
266	 */
267	async function runStage<T>(
268		state: RunState,
269		name: RunStageName,
270		stage: () => Promise<T>,
271	): Promise<T | null> {
272		const halted = state.halted;
273		if (halted !== null) {
274			const at = new Date().toISOString();
275			state.rows.push(
276				Object.freeze({
277					name,
278					status: 'not-run' as const,
279					reason: notRunBecause(halted.stage, halted.status),
280					startedAt: at,
281					endedAt: at,
282				}),
283			);
284			return null;
285		}
286		const startedAt = new Date().toISOString();
287		try {
288			const value = await stage();
289			state.rows.push(
290				Object.freeze({
291					name,
292					status: 'ran' as const,
293					record: value,
294					startedAt,
295					endedAt: new Date().toISOString(),
296				}),
297			);
298			return value;
299		} catch (error) {
300			const endedAt = new Date().toISOString();
301			const refusal = pipelineRefusalOf(error);
302			if (refusal !== null) {
303				state.rows.push(
304					Object.freeze({
305						name,
306						status: 'refused' as const,
307						reason: refusal.code,
308						refusal,
309						startedAt,
310						endedAt,
311					}),
312				);
313				state.halted = Object.freeze({ stage: name, status: 'refused' as const });
314				state.refusal = refusal;
315				return null;
316			}
317			/**
318			 * A defect is carried rather than rethrown, and it is carried here for
319			 * the same reason a refusal is: the stage table is the outcome a reader
320			 * needs, and an exception that escapes this seam takes the table with
321			 * it. The exit code is still 1 and the stage is still named, so nothing
322			 * a defect used to be scored as has changed.
323			 */
324			const message = error instanceof Error ? error.message : String(error);
325			state.rows.push(
326				Object.freeze({ name, status: 'defect' as const, reason: message, startedAt, endedAt }),
327			);
328			state.halted = Object.freeze({ stage: name, status: 'defect' as const });
329			state.defect = Object.freeze({ stage: name, message });
330			return null;
331		}
332	}
333	
334	/** The stage order with the declarations each stage is handed, and nothing run. */
335	export function runStagePlan(
336		flags: Readonly<Record<string, readonly string[]>>,
337	): readonly RunStagePlanRow[] {
338		return Object.freeze(
339			RUN_STAGES.map((name) =>
340				Object.freeze({
341					name,
342					forwards: Object.freeze(
343						RUN_STAGE_FLAGS[name].filter((flag) => flags[flag] !== undefined),
344					),
345				}),
346			),
347		);
348	}
349	
350	/**
351	 * Run all nine stages, or state which one stopped the run.
352	 *
353	 * The stages are composed here in order and nowhere else. Each one receives
354	 * the declarations its own command would give it, which is what makes the
355	 * refusing defaults survive the chain: nothing is widened on the way through.
356	 */
357	export async function runFullPipeline(declarations: RunDeclarations): Promise<RunRecord> {
358		const stagePlan = runStagePlan(declarations.flags);
359		const application = displayPath(declarations.appRoot);
360		const lane = displayPath(declarations.out);
361		const report = await readCoverageReportSlot();
362		if (declarations.dryRun)
363			return Object.freeze({
364				schema: RUN_SCHEMA,
365				flow: 'run' as const,
366				outcome: 'not-run' as const,
367				exitCode: EXIT_PROCEEDED,
368				application,
369				lane,
370				dryRun: true,
371				stagePlan,
372				stages: Object.freeze([]),
373				report,
374				notEstablished: Object.freeze([
375					'--dry-run was declared, so no stage ran. Nothing here establishes what any of them would have recorded, and nothing was written into the lane.',
376					...RUN_NOT_ESTABLISHED,
377					REPORT_NOT_ESTABLISHED[report.status],
378				]),
379			});
380		const state: RunState = { rows: [], halted: null, refusal: null, defect: null };
381		const analysis = await runStage(state, 'analyze', () =>
382			analyzeApplication(declarations.appRoot),
383		);
384		await runStage(state, 'ingest', () =>
385			ingestApplicationSource(declarations.sourceRoot, declarations.ingest),
386		);
387		await runStage(state, 'license-at-pin', async () => {
388			const frontendRoot = declarations.ingest.frontendRoot ?? '.';
389			const manifest = path.join(declarations.sourceRoot, frontendRoot, 'package.json');
390			return readLicenceAtPin(
391				declarations.sourceRoot,
392				(await fileExists(manifest)) ? manifest : null,
393				declarations.licence,
394			);
395		});
396		await runStage(state, 'era-cell', () =>
397			establishEraCell(declarations.appRoot, declarations.eraCell),
398		);
399		const planned = await runStage(state, 'plan', () =>
400			planApplication({
401				appRoot: declarations.appRoot,
402				angular: declarations.angular,
403				react: declarations.react,
404			}),
405		);
406		const applied = await runStage(state, 'apply', async () => {
407			if (planned === null || analysis === null)
408				throw new Error(
409					'run: the apply stage was reached without a plan. This is a defect in the chaining rather than a refusal: the stage order guarantees a plan before an apply.',
410				);
411			const changeset = await applyPlan(planned.plan, {
412				appRoot: declarations.appRoot,
413				out: declarations.out,
414				materialize: declarations.materialize,
415			});
416			const composition = await composeLane(
417				declarations.appRoot,
418				declarations.out,
419				planned.plan.lineage,
420				analysis.builder,
421			);
422			await writeLaneFiles(declarations.out, composition);
423			return {
424				applied: changeset,
425				laneComposition: {
426					...composition,
427					files: composition.files.map(({ source: _source, ...rest }) => rest),
428				},
429			};
430		});
431		await runStage(state, 'install', () =>
432			runLaneInstall(
433				declarations.out,
434				declarations.install,
435				process.env,
436				applied?.laneComposition.composed === true ? 'resolve' : 'replay',
437			),
438		);
439		const built = await runStage(state, 'build', () => runLaneBuild(declarations.out));
440		await runStage(state, 'witness', () =>
441			runLaneWitness({
442				application: path.basename(declarations.appRoot),
443				sourceRoot: declarations.appRoot,
444				laneBuild: path.join(declarations.out, built?.outDirectory ?? 'dist'),
445			}),
446		);
447		const halted = state.halted;
448		const exitCode =
449			halted === null ? EXIT_PROCEEDED : halted.status === 'refused' ? EXIT_REFUSAL : EXIT_DEFECT;
450		return Object.freeze({
451			schema: RUN_SCHEMA,
452			flow: 'run' as const,
453			outcome:
454				halted === null
455					? ('proceeded' as const)
456					: halted.status === 'refused'
457						? ('refused' as const)
458						: ('defect' as const),
459			exitCode,
460			application,
461			lane,
462			dryRun: false,
463			stagePlan,
464			stages: Object.freeze([...state.rows]),
465			...(state.refusal === null ? {} : { refusal: state.refusal }),
466			...(state.defect === null ? {} : { defect: state.defect }),
467			report,
468			notEstablished: Object.freeze([
469				...RUN_NOT_ESTABLISHED,
470				REPORT_NOT_ESTABLISHED[report.status],
471			]),
472		});
473	}
474	
475	const STAGE_COLUMN = Math.max(...RUN_STAGES.map((name) => name.length)) + 2;
476	
477	function renderStagePlan(plan: readonly RunStagePlanRow[]): readonly string[] {
478		return plan.map(
479			(row, index) =>
480				`  ${String(index + 1)}. ${row.name.padEnd(STAGE_COLUMN)}${
481					row.forwards.length === 0
482						? 'no declaration from this command line'
483						: row.forwards.join(' ')
484				}`,
485		);
486	}
487	
488	/** The run as an operator reads it: the stage table, then whatever stopped it. */
489	export function renderRun(record: RunRecord): string {
490		const lines = [`application: ${record.application}`, `lane: ${record.lane}`, ''];
491		if (record.dryRun) {
492			lines.push('dry run: the stage order and the declarations each stage would be given.');
493			lines.push('');
494			lines.push(...renderStagePlan(record.stagePlan));
495			lines.push('');
496			lines.push('No stage ran and nothing was written into the lane.');
497		} else {
498			for (const row of record.stages)
499				lines.push(
500					`  ${row.name.padEnd(STAGE_COLUMN)}${row.status.padEnd(10)}${row.reason ?? ''}`,
501				);
502			lines.push('');
503			lines.push(
504				record.outcome === 'proceeded'
505					? `all ${String(record.stages.length)} stage(s) proceeded.`
506					: record.outcome === 'refused'
507						? `stopped at ${record.refusal?.stage ?? ''}.`
508						: `stopped at ${record.defect?.stage ?? ''} with a defect.`,
509			);
510		}
511		lines.push('');
512		if (record.refusal !== undefined) lines.push(renderRefusal(record.refusal));
513		if (record.defect !== undefined) {
514			lines.push(`defect: ${record.defect.stage}`);
515			lines.push('');
516			lines.push(record.defect.message);
517			lines.push('');
518		}
519		lines.push(
520			record.report.status === 'emitted'
521				? `report: emitted at ${record.report.path} (${record.report.digest})`
522				: `report: ${record.report.status} (${record.report.slot}) — ${record.report.reason}`,
523		);
524		lines.push('');
525		for (const line of record.notEstablished) lines.push(`not established: ${line}`);
526		return `${lines.join('\n')}\n`;
527	}
528

